using System;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ZenithRingOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ZenithRing Omen Data")]
public class ZenithRingOmenData : OmenData
{
	private const string dealAdditionalPurifyID = "DealAdditionalPurify";

	[Header("Zenith Ring")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	private Func<int, int> omenAction;

	private CorruptionStats playerCorruptionStats;

	public override void Initialize(OmenInstance omenInstance)
	{
		playerCorruptionStats = playerGameObjectReference.value.GetComponent<CorruptionStats>();
		omenAction = delegate(int purifyAmount)
		{
			if (playerCorruptionStats.CurrentCorruption == 6f)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				return purifyAmount + ActionValue;
			}
			return purifyAmount;
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Add(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.ZenithRingFeedbackAction = delegate(float playerCurrentCorruption)
		{
			if (playerCurrentCorruption == 6f)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else
			{
				omenInstance.StopBlinkingFeedback();
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Remove(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.ZenithRingFeedbackAction = null;
	}

	public override string OmenConvertedDescription()
	{
		base.OmenConvertedDescription();
		return base.OmenConvertedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetDealAdditionalPurifyLocalizedDescription(ActionValue);
	}

	public string GetDealAdditionalPurifyLocalizedDescription(int additionalPurifyAmount)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("DealAdditionalPurify"), additionalPurifyAmount);
	}
}
